INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l66','have sth done','',NULL,'/hæv ˈsʌmθɪŋ dʌn/','I had my car washed.','我(请人)把车洗了。','She had her hair cut.','她(请人)把头发剪了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l66','break open','',NULL,'/breɪk ˈoʊpən/','They broke open the packing cases.','他们打开了包装箱。','He broke open the box with a hammer.','他用锤子把箱子砸开。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l66','in perfect condition','',NULL,'/ɪn ˈpɜːrfɪkt kənˈdɪʃən/','The engine was still in perfect condition.','引擎依然完好无损。','The car is in perfect condition.','这辆车状况完好。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l66','turn ... into','',NULL,'/tɜːrn ˈɪntuː/','The bees turned the engine into a hive.','蜜蜂把引擎变成了蜂房。','They turned the barn into a house.','他们把谷仓改成了住房。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',5,'am2_l66_gp1','choice','{"stem":"\"I don''t wash my car myself; I ___ at the garage.\"(请人洗车:have + 物 + 过去分词)","options":["wash it","have it wash","have washed it","have it washed"],"answer_index":3,"stem_cn":"我不自己洗车,送到修车行去洗。","explanation_cn":"\"请别人做某事\"用 have + 物 + 过去分词。✓ I have it washed at the garage. ✗ wash it:表自己洗;✗ have washed it:是自己\"已经洗完\";✗ have it wash:过去分词应是 washed。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',5,'am2_l66_gp1','choice','{"stem":"\"The French authorities ___ and moved back to France.\"(请人把飞机打包)","options":["had packaged the plane","had the plane packaged","had the plane package","packaged the plane"],"answer_index":1,"stem_cn":"法国当局请人把飞机打包运回。","explanation_cn":"\"请别人做某事\"用 have + 物 + 过去分词;此处过去时 had the plane packaged。✓ The French authorities had the plane packaged. ✗ packaged the plane:表自己动手打包;✗ had packaged the plane:是自己\"已打包完\";✗ had the plane package:应用过去分词 packaged。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',5,'am2_l66_gp1','choice','{"stem":"\"I''m not going to clean my suit myself; I''m going to ___.\"(请人洗西服)","options":["have it clean","have cleaned it","clean it","have it cleaned"],"answer_index":3,"stem_cn":"我不自己洗西服,要送去洗。","explanation_cn":"\"请别人做某事\"用 have + 物 + 过去分词。✓ I''m going to have it cleaned. ✗ clean it:表自己洗;✗ have cleaned it:是自己\"已洗完\";✗ have it clean:应用过去分词 cleaned。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',5,'am2_l66_gp1','choice','{"stem":"\"Someone else washed it for me — I ___.\"(请人把车洗了)","options":["had my car washed","washed my car","had my car wash","had washed my car"],"answer_index":0,"stem_cn":"别人替我洗的——我(请人)把车洗了。","explanation_cn":"别人替我洗=请别人做,用 have + 物 + 过去分词。✓ I had my car washed. ✗ washed my car:表自己洗;✗ had washed my car:是自己\"已洗完\";✗ had my car wash:应用过去分词 washed。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',5,'am2_l66_gp2','choice','{"stem":"\"___ your watch repaired?\"(疑问:你(请人)把表修好了吗)","options":["Do you had","Have you did","Did you have","Did you had"],"answer_index":2,"stem_cn":"你把表修好了吗?","explanation_cn":"\"请别人做\"的疑问借助 did:Did you have + 物 + 过去分词。✓ Did you have your watch repaired? ✗ Have you did:语序与形式都错;✗ Did you had:did 后用原形 have;✗ Do you had:时态形式错。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',5,'am2_l66_gp2','choice','{"stem":"\"I ___ my watch repaired.\"(否定:我没(请人)把表修好)","options":["didn''t have","wasn''t have","don''t had","hadn''t have"],"answer_index":0,"stem_cn":"我没有把表修好。","explanation_cn":"\"请别人做\"的否定借助 didn''t:didn''t have + 物 + 过去分词。✓ I didn''t have my watch repaired. ✗ don''t had:形式错;✗ hadn''t have:形式错;✗ wasn''t have:形式错。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',5,'am2_l66_gp2','choice','{"stem":"\"___ the house painted yet?\"(疑问完成体:你把房子刷好了吗)","options":["Had you have","Did you have had","Have you have","Have you had"],"answer_index":3,"stem_cn":"你把房子粉刷好了吗?","explanation_cn":"完成体疑问:Have you had + 物 + 过去分词。✓ Have you had the house painted yet? ✗ Did you have had:两个过去堆叠错;✗ Have you have:重复 have;✗ Had you have:形式错。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',5,'am2_l66_gp3','choice','{"stem":"\"My watch has stopped. I will have to ___.\"(将来:得去请人修表)","options":["have it repaired","repair it","have repaired it","have it repair"],"answer_index":0,"stem_cn":"我的表停了,得去把它修好。","explanation_cn":"将来\"得去请人修\"用 will have to have + 物 + 过去分词。✓ I will have to have it repaired. ✗ repair it:表自己修;✗ have repaired it:是自己\"已修完\";✗ have it repair:应用过去分词 repaired。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',5,'am2_l66_gp3','choice','{"stem":"\"The group only needs to have three engines ___.\"(需要请人重修三台发动机)","options":["rebuild","rebuilt","to rebuild","rebuilding"],"answer_index":1,"stem_cn":"这群人只需请人重修三台发动机。","explanation_cn":"\"请人重修\"用 have + 物 + 过去分词,填过去分词 rebuilt。✓ need to have three engines rebuilt. ✗ rebuild:原形不表\"被重修\";✗ rebuilding:现在分词不合;✗ to rebuild:不定式不合此结构。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',5,'am2_l66_gp3','choice','{"stem":"\"They are going to have the plane ___.\"(打算请人修复飞机)","options":["restoring","restore","restored","to restore"],"answer_index":2,"stem_cn":"他们打算请人把飞机修复。","explanation_cn":"\"请人修复\"用 have + 物 + 过去分词,填 restored。✓ going to have the plane restored. ✗ restore:原形;✗ restoring:现在分词;✗ to restore:不定式不合此结构。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',5,'am2_l66_gp4','choice','{"stem":"\"He ___ yesterday at the barber''s.\"(请人做:昨天理了发)","options":["had cut his hair","had his hair cut","cut his hair","had his hair cutting"],"answer_index":1,"stem_cn":"他昨天在理发店理了发。","explanation_cn":"\"请人理发\"用 have + 物 + 过去分词(cut 的过去分词仍是 cut)。✓ He had his hair cut yesterday. ✗ cut his hair:表自己剪;✗ had cut his hair:是自己\"已剪完\";✗ had his hair cutting:应用过去分词。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',5,'am2_l66_gp4','choice','{"stem":"\"These shoes are worn out; I must ___.\"(请人修鞋)","options":["repair them","have repaired them","have them repaired","have them repair"],"answer_index":2,"stem_cn":"这鞋穿破了,我得拿去修。","explanation_cn":"\"请人修鞋\"用 have + 物 + 过去分词。✓ I must have them repaired. ✗ repair them:表自己修;✗ have repaired them:是自己\"已修完\";✗ have them repair:应用过去分词 repaired。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',5,'am2_l66_gp5','choice','{"stem":"\"(American English) The team ___ restoring the plane.\"(美语:集合名词作整体用单数)","options":["are","is","have","were"],"answer_index":1,"stem_cn":"(美语)这个团队在修复飞机。","explanation_cn":"美语里 team 等集合名词作整体、用单数动词。✓ (American English) The team is restoring the plane. ✗ are:那是英式复数用法,美语课程不用;✗ were:时态与数都不合;✗ have:主谓不一致。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',5,'am2_l66_gp5','choice','{"stem":"\"(American English) The group ___ going to have the plane restored.\"(美语:集合名词用单数)","options":["is","were","are","have"],"answer_index":0,"stem_cn":"(美语)这群人打算请人修复飞机。","explanation_cn":"美语里 group 作整体、用单数动词。✓ The group is going to have the plane restored. ✗ are:英式复数,美语不用;✗ were:数与时态不合;✗ have:不一致。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',5,'am2_l66_gp5','choice','{"stem":"\"(American English) The audience ___ made up of school children.\"(美语:集合名词作整体用单数)","options":["are","have","is","were"],"answer_index":2,"stem_cn":"(美语)观众由学生组成。","explanation_cn":"美语里 audience 作整体、用单数动词。✓ The audience is made up of school children. ✗ are:英式复数,美语不用;✗ were:不合;✗ have:不一致。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',5,'am2_l66_gp6','choice','{"stem":"\"(American English) The crew ___ rescued from the water by helicopter.\"(美语:集合名词用单数,过去)","options":["were","was","have","are"],"answer_index":1,"stem_cn":"(美语)船员被直升机从水中救起。","explanation_cn":"美语里 crew 作整体、用单数动词,过去用 was。✓ The crew was rescued by helicopter. ✗ were:英式复数,美语不用;✗ are:时态不合;✗ have:不一致。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',5,'am2_l66_gp6','choice','{"stem":"\"(American English) The government ___ taken strong measures against inflation.\"(美语:集合名词用单数,完成体)","options":["has","were","have","are"],"answer_index":0,"stem_cn":"(美语)政府已采取有力措施抑制通胀。","explanation_cn":"美语里 government 作整体、用单数动词,完成体用 has。✓ The government has taken strong measures. ✗ have:英式复数,美语不用;✗ were / are:时态与数不合。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',5,'am2_l66_gp6','choice','{"stem":"\"A colony of bees ___ turned the engine into a hive.\"(集合名词作整体用单数)","options":["are","has","have","were"],"answer_index":1,"stem_cn":"一群蜜蜂把发动机变成了蜂房。","explanation_cn":"a colony of bees 作整体、用单数动词,完成体用 has。✓ A colony of bees has turned the engine into a hive. ✗ have:与整体不一致;✗ were / are:时态与数不合。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',6,NULL,'choice','{"stem":"美语里\"(汽车)后备箱\"常说:","options":["back box","boot","trunk","car case"],"answer_index":2,"explanation_cn":"美语\"(汽车)后备箱\"常说 trunk;英式说 boot。✓ Put the bags in the trunk. 把包放进后备箱。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',6,NULL,'choice','{"stem":"美语里\"(汽车)引擎盖\"常说:","options":["hood","engine lid","bonnet","front cover"],"answer_index":0,"explanation_cn":"美语\"(汽车)引擎盖\"常说 hood;英式说 bonnet。✓ He opened the hood to check the engine. 他打开引擎盖检查发动机。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',6,NULL,'choice','{"stem":"wreck 的意思是:","options":["引擎","(失事的)残骸","港口","货物"],"answer_index":1,"explanation_cn":"wreck = (失事的)残骸。✓ the wreck lay undisturbed 残骸无人问津地躺着。\n顺带记:引擎 = engine;港口 = port;货物 = cargo."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',6,NULL,'choice','{"stem":"rescue 的意思是:","options":["忽视","摧毁","营救,抢救","埋葬"],"answer_index":2,"explanation_cn":"rescue = 营救、抢救。✓ rare and worth rescuing 稀有且值得抢救。\n顺带记:摧毁 = destroy;埋葬 = bury;忽视 = ignore."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',6,NULL,'choice','{"stem":"preserve 的意思是:","options":["毁坏","出售","丢弃","保存,保护"],"answer_index":3,"explanation_cn":"preserve = 保存、保护。✓ preserved in beeswax 被蜂蜡保存下来。\n顺带记:毁坏 = ruin;出售 = sell;丢弃 = throw away."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',6,NULL,'choice','{"stem":"colony 的意思是:","options":["单独一只","群,群落","沙漠","森林"],"answer_index":1,"explanation_cn":"colony = 群、群落。✓ a colony of bees 一群蜜蜂。\n顺带记:单独一只 = a single one;森林 = forest;沙漠 = desert."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',7,NULL,'cloze','{"stem":"第 1 空","context":"The French authorities had the plane ___1___ and moved back to France. Now a group of enthusiasts is going to have the plane ___2___. They only need to have three engines ___3___. A colony of bees ___4___ turned the fourth engine into a hive.","blank_no":1,"options":["packaged","package","packaging","to package"],"answer_index":0,"explanation_cn":"\"请人做\"用 have + 物 + 过去分词,填 packaged。✓ had the plane packaged.\n✗ package:原形;✗ packaging:现在分词;✗ to package:不定式不合。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',7,NULL,'cloze','{"stem":"第 2 空","context":"The French authorities had the plane ___1___ and moved back to France. Now a group of enthusiasts is going to have the plane ___2___. They only need to have three engines ___3___. A colony of bees ___4___ turned the fourth engine into a hive.","blank_no":2,"options":["restored","restore","restoring","to restore"],"answer_index":0,"explanation_cn":"\"请人修复\"填过去分词 restored。✓ going to have the plane restored.\n✗ restore:原形;✗ restoring:现在分词;✗ to restore:不定式不合。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',7,NULL,'cloze','{"stem":"第 3 空","context":"The French authorities had the plane ___1___ and moved back to France. Now a group of enthusiasts is going to have the plane ___2___. They only need to have three engines ___3___. A colony of bees ___4___ turned the fourth engine into a hive.","blank_no":3,"options":["rebuilt","rebuild","rebuilding","to rebuild"],"answer_index":0,"explanation_cn":"\"请人重修\"填过去分词 rebuilt。✓ have three engines rebuilt.\n✗ rebuild:原形;✗ rebuilding:现在分词;✗ to rebuild:不定式不合。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',7,NULL,'cloze','{"stem":"第 4 空","context":"The French authorities had the plane ___1___ and moved back to France. Now a group of enthusiasts is going to have the plane ___2___. They only need to have three engines ___3___. A colony of bees ___4___ turned the fourth engine into a hive.","blank_no":4,"options":["had","have","were","was"],"answer_index":0,"explanation_cn":"a colony of bees 作整体、用单数,过去完成用 had。✓ A colony of bees had turned the engine into a hive.\n✗ have:与整体不一致;✗ were / was:构不成过去完成。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',8,NULL,'choice','{"stem":"Where and when did the old airplane come down?","options":["In France in 1989","On a busy city street in 1989","On a remote island in the South Pacific, in 1963","In the North Atlantic in 1963"],"answer_index":2,"explanation_cn":"课文说 In 1963, an old airplane came down on a remote island in the South Pacific。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',8,NULL,'choice','{"stem":"How was the wreck found again after so many years?","options":["It was rediscovered during an aerial survey of the island in 1989","The French navy searched for it","A fisherman found it","It was never really lost"],"answer_index":0,"explanation_cn":"课文说 Then in 1989, it was rediscovered during an aerial survey of the island。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',8,NULL,'choice','{"stem":"Why was the fourth engine still in perfect condition?","options":["It was kept in a museum","It had just been repaired","It was made of solid gold","A colony of bees had turned it into a hive, preserving it in beeswax"],"answer_index":3,"explanation_cn":"课文说 A colony of bees had turned the engine into a hive, and it was completely preserved in beeswax。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',9,NULL,'choice','{"stem":"你想说\"我请人洗了车(不是自己洗的)\"(have sth done):","options":["I had my car wash.","I had washed my car.","I had my car washed.","I washed my car."],"answer_index":2,"explanation_cn":"\"请别人做某事\"用 have + 物 + 过去分词。✓ I had my car washed. 场合:说明是请人洗的,不是自己洗。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',9,NULL,'choice','{"stem":"你想问\"你把表修好了吗?\"(请人修:have sth done 的疑问):","options":["Did you have your watch repaired?","Did you have your watch repair?","Did you had your watch repaired?","Have you repaired your watch?"],"answer_index":0,"explanation_cn":"\"请别人做\"的疑问借助 did + have + 物 + 过去分词。✓ Did you have your watch repaired? 场合:问对方是否请人修好了表。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',9,NULL,'choice','{"stem":"你想说\"(美语)这个团队打算修复那架飞机\"(集合名词用美语单数):","options":["The team be going to restore the plane.","The team were going to restores the plane.","The team are going to restore the plane.","The team is going to restore the plane."],"answer_index":3,"explanation_cn":"📌 美语里 team 等集合名词当作一个整体、用单数动词 is。✓ The team is going to restore the plane. 场合:美语课程一律用单数(英式有时用 are,本课程不用)。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',10,NULL,'choice','{"stem":"wreck 的意思是:","options":["港口","货物","(失事的)残骸","引擎"],"answer_index":2,"explanation_cn":"wreck = (失事的)残骸。✓ the wreck lay undisturbed 残骸无人问津。\n顺带记:引擎 = engine;港口 = port;货物 = cargo."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',10,NULL,'choice','{"stem":"rescue 的意思是:","options":["营救,抢救","摧毁","忽视","埋葬"],"answer_index":0,"explanation_cn":"rescue = 营救、抢救。✓ worth rescuing 值得抢救。\n顺带记:摧毁 = destroy;埋葬 = bury;忽视 = ignore."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',10,NULL,'choice','{"stem":"\"He ___ yesterday at the barber''s.\"(请人做:昨天理了发)","options":["had his hair cutting","cut his hair","had cut his hair","had his hair cut"],"answer_index":3,"stem_cn":"他昨天在理发店理了发。","explanation_cn":"\"请人理发\"用 have + 物 + 过去分词。✓ He had his hair cut yesterday.\n✗ cut his hair:表自己剪;✗ had cut his hair:是自己\"已剪完\";✗ had his hair cutting:应用过去分词。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',10,NULL,'choice','{"stem":"\"(American English) The group ___ going to have the plane restored.\"(集合名词用美语单数)","options":["were","are","is","have"],"answer_index":2,"stem_cn":"(美语)这群人打算请人修复飞机。","explanation_cn":"📌 美语里 group 等集合名词作整体、用单数动词 is。✓ The group is going to have the plane restored.\n✗ are:英式复数,美语不用;✗ were:数与时态不合;✗ have:不一致。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',10,NULL,'choice','{"stem":"\"have + 物 + 过去分词\" 这种结构表示:","options":["自己亲手做某事","请/让别人做某事","将要亲自去做","已经做完某事"],"answer_index":1,"explanation_cn":"have + 物 + 过去分词表示请/让别人做某事(自己不亲自做),如 have my car washed=请人洗车。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',10,NULL,'choice','{"stem":"\"in perfect condition\" 的意思是:","options":["刚刚做好","快要坏了","正在维修","完好无损"],"answer_index":3,"explanation_cn":"in perfect condition = 完好无损、状况极佳。✓ still in perfect condition 依然完好无损。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',10,NULL,'choice','{"stem":"What did the French authorities do with the plane?","options":["They had it packaged and moved back to France in parts","They left it on the island","They rebuilt it on the island","They sold it to a museum"],"answer_index":0,"passage":"In 1963, an old airplane came down on a remote island in the South Pacific, a long way from anywhere. The plane wasn''t badly damaged, but over the years it was forgotten, and the wreck lay undisturbed. Then in 1989, it was rediscovered during an aerial survey of the island. By then, a plane in such condition was rare and worth rescuing. The French authorities had the plane packaged and moved back to France in parts. Now a group of enthusiasts is going to have the plane restored. It has four engines, but the group only needs to have three of them rebuilt. Imagine their surprise when they broke open the packing cases! The fourth engine was sweet as honey — still in perfect condition. A colony of bees had turned the engine into a hive, and it was completely preserved in beeswax!","explanation_cn":"课文说 The French authorities had the plane packaged and moved back to France in parts。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',10,NULL,'choice','{"stem":"What surprising thing was found in the fourth engine?","options":["It had been stolen","It was full of gold coins","It was completely rusted","A colony of bees had turned it into a hive, preserved in beeswax"],"answer_index":3,"passage":"In 1963, an old airplane came down on a remote island in the South Pacific, a long way from anywhere. The plane wasn''t badly damaged, but over the years it was forgotten, and the wreck lay undisturbed. Then in 1989, it was rediscovered during an aerial survey of the island. By then, a plane in such condition was rare and worth rescuing. The French authorities had the plane packaged and moved back to France in parts. Now a group of enthusiasts is going to have the plane restored. It has four engines, but the group only needs to have three of them rebuilt. Imagine their surprise when they broke open the packing cases! The fourth engine was sweet as honey — still in perfect condition. A colony of bees had turned the engine into a hive, and it was completely preserved in beeswax!","explanation_cn":"课文说 A colony of bees had turned the engine into a hive, and it was completely preserved in beeswax。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',10,NULL,'choice','{"stem":"How many of the four engines does the group need to have rebuilt?","options":["All four","Only three","None","Just one"],"answer_index":1,"audio":"In 1963, an old airplane came down on a remote island in the South Pacific, a long way from anywhere. The plane wasn''t badly damaged, but over the years it was forgotten, and the wreck lay undisturbed. Then in 1989, it was rediscovered during an aerial survey of the island. By then, a plane in such condition was rare and worth rescuing. The French authorities had the plane packaged and moved back to France in parts. Now a group of enthusiasts is going to have the plane restored. It has four engines, but the group only needs to have three of them rebuilt. Imagine their surprise when they broke open the packing cases! The fourth engine was sweet as honey — still in perfect condition. A colony of bees had turned the engine into a hive, and it was completely preserved in beeswax!","explanation_cn":"课文说 the group only needs to have three of them rebuilt(四台里只需修三台)。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l66',10,NULL,'choice','{"stem":"What was ''sweet as honey''?","options":["The island''s fruit","A jar of real honey","The pilot''s lunch","The fourth engine, which bees had preserved in beeswax"],"answer_index":3,"audio":"In 1963, an old airplane came down on a remote island in the South Pacific, a long way from anywhere. The plane wasn''t badly damaged, but over the years it was forgotten, and the wreck lay undisturbed. Then in 1989, it was rediscovered during an aerial survey of the island. By then, a plane in such condition was rare and worth rescuing. The French authorities had the plane packaged and moved back to France in parts. Now a group of enthusiasts is going to have the plane restored. It has four engines, but the group only needs to have three of them rebuilt. Imagine their surprise when they broke open the packing cases! The fourth engine was sweet as honey — still in perfect condition. A colony of bees had turned the engine into a hive, and it was completely preserved in beeswax!","explanation_cn":"课文说 The fourth engine was sweet as honey… A colony of bees had turned it into a hive, preserved in beeswax。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l67',2,9,67,'Volcanoes','火山','KS43 can/could 表能力、be able to 与 manage to 表''设法做成一件具体的难事''(过去成功 was able to / managed to;没能做成 couldn''t = wasn''t able to = didn''t manage to)(教材 L67 Key structures)主考;SD 带 say 与 tell 的短语辨析(say so/said his prayers/say a good word vs tell the time/tell lies/tell the difference)(辅考)','波兰科学家哈罗恩·塔捷耶夫花了毕生的精力来研究世界各地的活火山和深洞。1948年他去了刚果的基伍湖,对一座后来被他命名为基图罗的新火山进行观察。当火山正在猛烈地喷发时,塔捷耶夫有办法把帐篷搭在离它非常近的地方。尽管他设法拍了一些十分精彩的照片,但他却不能在火山附近停留太长的时间。他发现有一股岩浆正向他流过来,眼看就要将他团团围住,但塔捷耶夫还是设法及时逃离了。他等到火山平静下来,两天以后又返回去。这次他设法爬进了基图罗火山口,以便能拍摄照片和测试温度。塔捷耶夫经常冒这样的生命危险。他能告诉我们的有关活火山的情况比任何在世的人都要多。','{"q":"Listen and answer — Why does Tazieff risk his life like this?","options":["So he can study active volcanoes up close and tell us more about them than anyone alive","Because he is paid a lot of money","Because he enjoys the danger","Because he is trying to stop the volcanoes"],"answer_index":0}'::jsonb,'{"title":"can / be able to / manage to","intro":"KS43 表能力与''做成'':①can/could = 一般的能力(As a boy he could swim well);②was able to / managed to = 过去''设法做成了一件具体的、有难度的事''(He managed to set up his camp = He was able to set up his camp);③没能做成 = couldn''t = wasn''t able to = didn''t manage to。managed to 尤其强调''费了劲、终于成功''。","table":{"headers":["意思","用法","例子"],"rows":[["一般能力","can / could","As a boy he could swim well."],["成功做成(过去)","was able to / managed to","He managed to escape just in time."],["没能做成","couldn''t / wasn''t able to / didn''t manage to","I didn''t manage to get into town."]]},"specialRules":[{"rule":"managed to 可代替 was able to 表示''成功地完成了动作'';反过来,could not 也可用 didn''t manage to 表达''没能做成''。","mark":"manage to = be able to"},{"rule":"SD 带 say 的短语:say so、say nothing、say a good word for、said his prayers、say goodbye、say no more;带 tell 的短语:tell the time、tell lies、tell the truth、tell a story、tell a secret、tell the difference。","mark":"say / tell 短语"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l67',1,NULL,'Haroun Tazieff, the Polish scientist, has spent his lifetime studying active volcanoes and deep caves in all parts of the world. In 1948, he went to Lake Kivu in the Congo to observe a new volcano which he later named Kituro.','波兰科学家哈罗恩·塔捷耶夫花了毕生的精力来研究世界各地的活火山和深洞。1948年他去了刚果的基伍湖,对一座后来被他命名为基图罗的新火山进行观察。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l67',2,NULL,'Tazieff was able to set up his camp very close to the volcano while it was erupting violently. Though he managed to take a number of brilliant photographs, he could not stay near the volcano for very long.','当火山正在猛烈地喷发时,塔捷耶夫有办法把帐篷搭在离它非常近的地方。尽管他设法拍了一些十分精彩的照片,但他却不能在火山附近停留太长的时间。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l67',3,NULL,'He noticed that a river of liquid rock was coming towards him. It threatened to surround him completely, but Tazieff managed to escape just in time.','他发现有一股岩浆正向他流过来,眼看就要将他团团围住,但塔捷耶夫还是设法及时逃离了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l67',4,NULL,'He waited until the volcano became quiet and he was able to return two days later. This time, he managed to climb into the mouth of Kituro so that he could take photographs and measure temperatures.','他等到火山平静下来,两天以后又返回去。这次他设法爬进了基图罗火山口,以便能拍摄照片和测试温度。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l67',5,NULL,'Tazieff has often risked his life in this way. He has been able to tell us more about active volcanoes than any man alive.','塔捷耶夫经常冒这样的生命危险。他能告诉我们的有关活火山的情况比任何在世的人都要多。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
