INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l67_gp1','am2_l67','can / could 表一般能力',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l67_gp2','am2_l67','was able to / managed to(过去成功做成)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l67_gp3','am2_l67','没能做成 couldn''t = wasn''t able to = didn''t manage to',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l67_gp4','am2_l67','带 say 的短语(SD)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l67_gp5','am2_l67','带 tell 的短语(SD)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l67_gp6','am2_l67','say vs tell 辨析(SD)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l67','center','centre','中心;美语 center,英式 centre(-er vs -re)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l67','meter','metre','米、公尺;美语 meter,英式 metre') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l67','liter','litre','升;美语 liter,英式 litre') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l67','theater','theatre','剧院;美语 theater,英式 theatre') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l67','set up (a camp)','',NULL,'/set ʌp/','He managed to set up his camp near the volcano.','他设法在火山附近扎了营。','They set up a tent by the river.','他们在河边搭起了帐篷。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l67','just in time','',NULL,'/dʒʌst ɪn taɪm/','He managed to escape just in time.','他设法及时逃离了。','We got there just in time.','我们及时赶到了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l67','spend one''s lifetime doing','',NULL,'/spend ˈlaɪftaɪm ˈduːɪŋ/','He has spent his lifetime studying volcanoes.','他毕生研究火山。','She spent her lifetime helping others.','她一生都在帮助他人。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l67','risk one''s life','',NULL,'/rɪsk wʌnz laɪf/','Tazieff has often risked his life.','塔捷耶夫经常冒生命危险。','Firefighters risk their lives every day.','消防员每天都冒着生命危险。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',5,'am2_l67_gp1','choice','{"stem":"\"As a boy, he ___ swim very well.\"(过去的一般能力)","options":["was able","managed to","did","could"],"answer_index":3,"stem_cn":"他小时候游泳游得很好。","explanation_cn":"过去的一般能力用 could。✓ As a boy, he could swim very well. ✗ managed to:用于\"设法做成一件具体的难事\",不表一般能力;✗ was able:缺 to;✗ did:不表能力。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',5,'am2_l67_gp1','choice','{"stem":"\"I ___ understand him; he spoke too fast.\"(过去做不到——否定能力)","options":["didn''t could","couldn''t","don''t could","wasn''t able"],"answer_index":1,"stem_cn":"我听不懂他,他说得太快了。","explanation_cn":"过去做不到用 couldn''t(= wasn''t able to)。✓ I couldn''t understand him; he spoke too fast. ✗ didn''t could:形式错;✗ wasn''t able:缺 to;✗ don''t could:形式错。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',5,'am2_l67_gp2','choice','{"stem":"\"The volcano was erupting, but Tazieff ___ set up his camp close to it.\"(过去成功做成一件难事)","options":["must","could","managed to","may"],"answer_index":2,"stem_cn":"火山在喷发,但塔捷耶夫设法把营地扎在了附近。","explanation_cn":"过去\"设法做成了一件有难度的事\"用 managed to。✓ Tazieff managed to set up his camp close to it. ✗ could:表一般能力,不强调这一次费劲做成;✗ must:表推测/必须;✗ may:表可能。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',5,'am2_l67_gp2','choice','{"stem":"\"He ___ take a number of brilliant photographs.\"(过去成功拍到了照片)","options":["could to","can","managed","was able to"],"answer_index":3,"stem_cn":"他设法拍了一些精彩的照片。","explanation_cn":"过去成功做成某事用 was able to(= managed to)。✓ He was able to take a number of brilliant photographs. ✗ could to:could 后不加 to;✗ managed:缺 to;✗ can:是现在。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',5,'am2_l67_gp2','choice','{"stem":"\"He didn''t agree at first, but I ___ persuade him.\"(过去成功说服了他)","options":["managed to","could","would","must"],"answer_index":0,"stem_cn":"他起初不同意,但我设法说服了他。","explanation_cn":"过去费劲终于做成用 managed to。✓ I managed to persuade him. ✗ could:表一般能力;✗ must:必须/推测;✗ would:表意愿/过去习惯。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',5,'am2_l67_gp2','choice','{"stem":"\"The volcano became quiet and he ___ return two days later.\"(过去成功返回)","options":["could to","managed","was able to","can"],"answer_index":2,"stem_cn":"火山平静下来,两天后他得以返回。","explanation_cn":"过去成功做成(得以返回)用 was able to。✓ He was able to return two days later. ✗ could to:could 不加 to;✗ can:现在;✗ managed:缺 to。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',5,'am2_l67_gp3','choice','{"stem":"\"I ___ get into town this morning.\"(= I could not;''没能''进城)","options":["didn''t manage to","don''t manage to","didn''t managed to","not managed to"],"answer_index":0,"stem_cn":"今天上午我没能进城。","explanation_cn":"\"没能做成\"= could not = didn''t manage to。✓ I didn''t manage to get into town this morning. ✗ didn''t managed to:did 后用原形 manage;✗ don''t manage to:是现在;✗ not managed to:缺助动词。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',5,'am2_l67_gp3','choice','{"stem":"\"They ___ find the boy who had run away.\"(''没能''找到)","options":["wasn''t able to","couldn''t to","didn''t able to","weren''t able to"],"answer_index":3,"stem_cn":"他们没能找到那个跑掉的男孩。","explanation_cn":"\"没能做成\"用 wasn''t/weren''t able to;主语 They 用 weren''t。✓ They weren''t able to find the boy. ✗ wasn''t able to:主语复数不用 wasn''t;✗ couldn''t to:couldn''t 不加 to;✗ didn''t able to:形式错。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',5,'am2_l67_gp3','choice','{"stem":"\"He ___ find a new job.\"(''没能''找到新工作)","options":["not manage to","couldn''t to","didn''t manage to","didn''t managed to"],"answer_index":2,"stem_cn":"他没能找到新工作。","explanation_cn":"\"没能做成\"= didn''t manage to。✓ He didn''t manage to find a new job. ✗ didn''t managed to:did 后用原形;✗ couldn''t to:couldn''t 不加 to;✗ not manage to:缺助动词。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',5,'am2_l67_gp4','choice','{"stem":"\"Did he ___ anything to you about it?\"(选词:''对某人说起某事'')","options":["speak","say","talk","tell"],"answer_index":1,"stem_cn":"他有没有跟你说过这事?","explanation_cn":"\"对某人说些什么\"用 say(say something to sb)。✓ Did he say anything to you about it? ✗ tell:tell 后一般直接跟人(tell you);✗ speak:speak 不接\"内容\";✗ talk:同理。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',5,'am2_l67_gp4','choice','{"stem":"\"He knelt down and ___ his prayers.\"(选词:''做祷告''的固定说法)","options":["spoke","told","said","talked"],"answer_index":2,"stem_cn":"他跪下来做祷告。","explanation_cn":"固定短语 say one''s prayers = 做祷告。✓ He knelt down and said his prayers. ✗ told:不与 prayers 搭配;✗ spoke / talked:不与 prayers 搭配。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',5,'am2_l67_gp4','choice','{"stem":"\"If you want more cake, please ___ so.\"(选词:''(这么)说一声'')","options":["say","speak","talk","tell"],"answer_index":0,"stem_cn":"想再要蛋糕就说一声。","explanation_cn":"固定短语 say so = (这么)说一声。✓ If you want more cake, please say so. ✗ tell:tell 后要跟人;✗ speak / talk:不与 so 构成这个短语。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',5,'am2_l67_gp5','choice','{"stem":"\"Can you ___ the time in English?\"(选词:''报时、说出几点'')","options":["talk","tell","say","speak"],"answer_index":1,"stem_cn":"你能用英语报时吗?","explanation_cn":"固定短语 tell the time = 报时、看钟点。✓ Can you tell the time in English? ✗ say / speak / talk:都不与 the time 构成\"报时\"这个短语。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',5,'am2_l67_gp5','choice','{"stem":"\"He often ___ lies.\"(选词:''说谎''的固定说法)","options":["tells","says","speaks","talks"],"answer_index":0,"stem_cn":"他经常说谎。","explanation_cn":"固定短语 tell lies = 说谎;主语 He 用 tells。✓ He often tells lies. ✗ says / speaks / talks:都不与 lies 搭配。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',5,'am2_l67_gp5','choice','{"stem":"\"Can''t you ___ the difference between them?\"(选词:''区分、分辨'')","options":["speak","tell","know","say"],"answer_index":1,"stem_cn":"你分不出它们的区别吗?","explanation_cn":"固定短语 tell the difference = 区分、分辨。✓ Can''t you tell the difference between them? ✗ say / speak:不与 the difference 搭配;✗ know:此处习惯用 tell。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',5,'am2_l67_gp6','choice','{"stem":"\"He is only five, but he can already ___ the time.\"(报时用哪个词)","options":["talk","speak","tell","say"],"answer_index":2,"stem_cn":"他才5岁,但已经会看钟点了。","explanation_cn":"\"报时、看钟点\"用 tell the time。✓ He can already tell the time. ✗ say / speak / talk:不与 the time 构成\"报时\"。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',5,'am2_l67_gp6','choice','{"stem":"\"They asked the prisoner several questions, but he ___ nothing.\"(什么也没说用哪个词)","options":["spoke","said","talked","told"],"answer_index":1,"stem_cn":"他们问了犯人几个问题,但他什么也没说。","explanation_cn":"\"什么也没说\"用 say nothing。✓ He said nothing. ✗ told:后要跟人;✗ spoke / talked:不接\"内容\"这样用。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',5,'am2_l67_gp6','choice','{"stem":"\"I want you to ___ me the truth.\"(告诉我实话用哪个词)","options":["tell","talk","say","speak"],"answer_index":0,"stem_cn":"我要你跟我说实话。","explanation_cn":"\"告诉我实话\"用 tell sb the truth。✓ I want you to tell me the truth. ✗ say:后不直接跟人;✗ speak / talk:不这样搭配。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',6,NULL,'choice','{"stem":"美语里\"中心、中央\"拼作:","options":["centre","centr","sentre","center"],"answer_index":3,"explanation_cn":"美语\"中心、中央\"拼作 center;英式拼作 centre(-er vs -re)。✓ the red center of the volcano 火山通红的中心。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',6,NULL,'choice','{"stem":"美语里\"米、公尺\"拼作:","options":["meter","metr","metter","metre"],"answer_index":0,"explanation_cn":"美语\"米、公尺\"拼作 meter;英式拼作 metre。✓ a few meters away 几米开外。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',6,NULL,'choice','{"stem":"volcano 的意思是:","options":["冰川","火山","地震","海啸"],"answer_index":1,"explanation_cn":"volcano = 火山。✓ active volcanoes 活火山。\n顺带记:地震 = earthquake;海啸 = tsunami;冰川 = glacier."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',6,NULL,'choice','{"stem":"erupt 的意思是:","options":["熄灭","干涸","(火山)喷发","冻结"],"answer_index":2,"explanation_cn":"erupt = (火山)喷发。✓ while it was erupting violently 当它正猛烈喷发时。\n顺带记:熄灭 = go out;冻结 = freeze;干涸 = dry up."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',6,NULL,'choice','{"stem":"escape 的意思是:","options":["到达","停留","返回","逃脱,逃离"],"answer_index":3,"explanation_cn":"escape = 逃脱、逃离。✓ managed to escape just in time 设法及时逃离。\n顺带记:到达 = arrive;停留 = stay;返回 = return."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',6,NULL,'choice','{"stem":"brilliant 的意思是:","options":["平凡的","昂贵的","精彩的,极好的","糟糕的"],"answer_index":2,"explanation_cn":"brilliant = 精彩的、极好的。✓ a number of brilliant photographs 一些精彩的照片。\n顺带记:平凡的 = ordinary;糟糕的 = terrible;昂贵的 = expensive."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',7,NULL,'cloze','{"stem":"第 1 空","context":"Tazieff ___1___ set up his camp close to the volcano while it was erupting. Though he took brilliant photographs, he ___2___ stay near it for very long. He escaped just in time, and later he ___3___ return. This time he ___4___ climb into the mouth of Kituro.","blank_no":1,"options":["managed to","could","must","may"],"answer_index":0,"explanation_cn":"过去成功做成一件难事用 managed to。✓ Tazieff managed to set up his camp close to the volcano.\n✗ could:表一般能力;✗ must:必须/推测;✗ may:可能。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',7,NULL,'cloze','{"stem":"第 2 空","context":"Tazieff ___1___ set up his camp close to the volcano while it was erupting. Though he took brilliant photographs, he ___2___ stay near it for very long. He escaped just in time, and later he ___3___ return. This time he ___4___ climb into the mouth of Kituro.","blank_no":2,"options":["couldn''t","managed to","was able to","could to"],"answer_index":0,"explanation_cn":"过去做不到用 couldn''t。✓ he couldn''t stay near it for very long.\n✗ managed to / was able to:表\"做成了\",与\"不能久留\"矛盾;✗ could to:could 不加 to。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',7,NULL,'cloze','{"stem":"第 3 空","context":"Tazieff ___1___ set up his camp close to the volcano while it was erupting. Though he took brilliant photographs, he ___2___ stay near it for very long. He escaped just in time, and later he ___3___ return. This time he ___4___ climb into the mouth of Kituro.","blank_no":3,"options":["was able to","could to","can","managed"],"answer_index":0,"explanation_cn":"过去成功做成(得以返回)用 was able to。✓ later he was able to return.\n✗ could to:could 不加 to;✗ can:现在;✗ managed:缺 to。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',7,NULL,'cloze','{"stem":"第 4 空","context":"Tazieff ___1___ set up his camp close to the volcano while it was erupting. Though he took brilliant photographs, he ___2___ stay near it for very long. He escaped just in time, and later he ___3___ return. This time he ___4___ climb into the mouth of Kituro.","blank_no":4,"options":["managed to","could to","can","must"],"answer_index":0,"explanation_cn":"过去费劲做成用 managed to。✓ This time he managed to climb into the mouth of Kituro.\n✗ could to:could 不加 to;✗ can:现在;✗ must:必须/推测。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',8,NULL,'choice','{"stem":"What has Haroun Tazieff spent his lifetime doing?","options":["Studying active volcanoes and deep caves all over the world","Teaching at a university","Sailing across the oceans","Painting pictures of mountains"],"answer_index":0,"explanation_cn":"课文说 Haroun Tazieff has spent his lifetime studying active volcanoes and deep caves in all parts of the world。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',8,NULL,'choice','{"stem":"What happened while Tazieff was near the erupting volcano in 1948?","options":["He was trapped for two days","A river of liquid rock came towards him, but he managed to escape just in time","He fell into the volcano","His camera was destroyed"],"answer_index":1,"explanation_cn":"课文说 a river of liquid rock was coming towards him… but Tazieff managed to escape just in time。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',8,NULL,'choice','{"stem":"Why can Tazieff tell us more about active volcanoes than any man alive?","options":["Because he has special machines","Because he reads many books","Because he lives on a volcano","Because he has often risked his life to study them up close"],"answer_index":3,"explanation_cn":"课文说 Tazieff has often risked his life in this way, and he can tell us more about active volcanoes than any man alive。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',9,NULL,'choice','{"stem":"你想说\"火山在喷发,但他设法把营地扎在了附近\"(成功做成一件难事用 manage to):","options":["The volcano was erupting, but he managed set up his camp nearby.","The volcano was erupting, but he managed to set up his camp nearby.","The volcano was erupting, but he could set up his camp nearby.","The volcano was erupting, but he was able set up his camp nearby."],"answer_index":1,"explanation_cn":"过去\"设法做成一件难事\"用 managed to。✓ he managed to set up his camp nearby. 场合:强调费劲、终于做成。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',9,NULL,'choice','{"stem":"你想说\"今天上午我没能进城\"(= I could not,用 didn''t manage to):","options":["I don''t manage to get into town this morning.","I couldn''t to get into town this morning.","I didn''t manage to get into town this morning.","I didn''t managed to get into town this morning."],"answer_index":2,"explanation_cn":"\"没能做成\"= didn''t manage to(= could not)。✓ I didn''t manage to get into town this morning. 场合:说自己没能办成某事。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',9,NULL,'choice','{"stem":"你想说\"请给我们讲个故事\"(用 tell):","options":["Please say us a story.","Please speak us a story.","Please talk us a story.","Please tell us a story."],"answer_index":3,"explanation_cn":"\"讲故事\"用 tell(tell sb a story)。✓ Please tell us a story. 场合:请人讲故事时用 tell,不用 say/speak/talk。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',10,NULL,'choice','{"stem":"volcano 的意思是:","options":["海啸","火山","地震","冰川"],"answer_index":1,"explanation_cn":"volcano = 火山。✓ active volcanoes 活火山。\n顺带记:地震 = earthquake;海啸 = tsunami;冰川 = glacier."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',10,NULL,'choice','{"stem":"escape 的意思是:","options":["到达","返回","逃脱,逃离","停留"],"answer_index":2,"explanation_cn":"escape = 逃脱、逃离。✓ managed to escape just in time 设法及时逃离。\n顺带记:到达 = arrive;停留 = stay;返回 = return."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',10,NULL,'choice','{"stem":"\"The volcano was erupting, but Tazieff ___ set up his camp close to it.\"(过去成功做成)","options":["managed to","could","may","must"],"answer_index":0,"stem_cn":"火山在喷发,但塔捷耶夫设法把营地扎在了附近。","explanation_cn":"过去成功做成一件难事用 managed to。✓ Tazieff managed to set up his camp close to it.\n✗ could:表一般能力;✗ must:必须/推测;✗ may:可能。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',10,NULL,'choice','{"stem":"\"He often ___ lies.\"(说谎用哪个词)","options":["speaks","tells","says","talks"],"answer_index":1,"stem_cn":"他经常说谎。","explanation_cn":"固定短语 tell lies = 说谎;主语 He 用 tells。✓ He often tells lies.\n✗ says / speaks / talks:都不与 lies 搭配。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',10,NULL,'choice','{"stem":"\"managed to do\" 表示的意思是:","options":["打算去做","忘记去做","设法做成了(成功完成一件难事)","拒绝去做"],"answer_index":2,"explanation_cn":"managed to do = 设法做成了某事(费了劲、终于成功),= was able to do。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',10,NULL,'choice','{"stem":"\"risk one''s life\" 的意思是:","options":["浪费生命","冒生命危险","挽救生命","珍惜生命"],"answer_index":1,"explanation_cn":"risk one''s life = 冒生命危险。✓ Tazieff has often risked his life 塔捷耶夫经常冒生命危险。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',10,NULL,'choice','{"stem":"Why couldn''t Tazieff stay near the volcano for very long the first time?","options":["He ran out of film","The volcano stopped erupting","It was getting dark","A river of liquid rock was coming towards him and threatened to surround him"],"answer_index":3,"passage":"Haroun Tazieff, the Polish scientist, has spent his lifetime studying active volcanoes and deep caves in all parts of the world. In 1948, he went to Lake Kivu in the Congo to observe a new volcano which he later named Kituro. Tazieff was able to set up his camp very close to the volcano while it was erupting violently. Though he managed to take a number of brilliant photographs, he could not stay near the volcano for very long. He noticed that a river of liquid rock was coming towards him. It threatened to surround him completely, but Tazieff managed to escape just in time. He waited until the volcano became quiet and he was able to return two days later. This time, he managed to climb into the mouth of Kituro so that he could take photographs and measure temperatures. Tazieff has often risked his life in this way. He has been able to tell us more about active volcanoes than any man alive.","explanation_cn":"课文说 a river of liquid rock was coming towards him. It threatened to surround him completely,所以他不能久留。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',10,NULL,'choice','{"stem":"What did Tazieff manage to do when he returned two days later?","options":["He filled in the volcano","He gave up his research","He climbed into the mouth of Kituro to take photos and measure temperatures","He built a house there"],"answer_index":2,"passage":"Haroun Tazieff, the Polish scientist, has spent his lifetime studying active volcanoes and deep caves in all parts of the world. In 1948, he went to Lake Kivu in the Congo to observe a new volcano which he later named Kituro. Tazieff was able to set up his camp very close to the volcano while it was erupting violently. Though he managed to take a number of brilliant photographs, he could not stay near the volcano for very long. He noticed that a river of liquid rock was coming towards him. It threatened to surround him completely, but Tazieff managed to escape just in time. He waited until the volcano became quiet and he was able to return two days later. This time, he managed to climb into the mouth of Kituro so that he could take photographs and measure temperatures. Tazieff has often risked his life in this way. He has been able to tell us more about active volcanoes than any man alive.","explanation_cn":"课文说 he managed to climb into the mouth of Kituro so that he could take photographs and measure temperatures。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',10,NULL,'choice','{"stem":"Where did Tazieff go in 1948?","options":["To a desert in Africa","To Lake Kivu in the Congo, to observe a new volcano he named Kituro","To the North Pole","To a cave in Poland"],"answer_index":1,"audio":"Haroun Tazieff, the Polish scientist, has spent his lifetime studying active volcanoes and deep caves in all parts of the world. In 1948, he went to Lake Kivu in the Congo to observe a new volcano which he later named Kituro. Tazieff was able to set up his camp very close to the volcano while it was erupting violently. Though he managed to take a number of brilliant photographs, he could not stay near the volcano for very long. He noticed that a river of liquid rock was coming towards him. It threatened to surround him completely, but Tazieff managed to escape just in time. He waited until the volcano became quiet and he was able to return two days later. This time, he managed to climb into the mouth of Kituro so that he could take photographs and measure temperatures. Tazieff has often risked his life in this way. He has been able to tell us more about active volcanoes than any man alive.","explanation_cn":"课文说 In 1948, he went to Lake Kivu in the Congo to observe a new volcano which he later named Kituro。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l67',10,NULL,'choice','{"stem":"How does the passage describe Tazieff''s knowledge of active volcanoes?","options":["He can tell us more about them than any man alive","He only studies dead volcanoes","He knows nothing about them","He has never seen one"],"answer_index":0,"audio":"Haroun Tazieff, the Polish scientist, has spent his lifetime studying active volcanoes and deep caves in all parts of the world. In 1948, he went to Lake Kivu in the Congo to observe a new volcano which he later named Kituro. Tazieff was able to set up his camp very close to the volcano while it was erupting violently. Though he managed to take a number of brilliant photographs, he could not stay near the volcano for very long. He noticed that a river of liquid rock was coming towards him. It threatened to surround him completely, but Tazieff managed to escape just in time. He waited until the volcano became quiet and he was able to return two days later. This time, he managed to climb into the mouth of Kituro so that he could take photographs and measure temperatures. Tazieff has often risked his life in this way. He has been able to tell us more about active volcanoes than any man alive.","explanation_cn":"课文说 He has been able to tell us more about active volcanoes than any man alive。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l68',2,9,68,'Persistent','甩不掉的人','KS20+KS44 动名词 -ing 作动词宾语(avoid/enjoy/deny/finish/mind + doing;It''s no use/not worth doing、be busy doing、prevent sb from doing)(教材 L68 Key structures)主考;动名词的逻辑主语(mind my doing)、感官动词 see/hear/smell + doing、go/come + doing、反义疑问句(辅考)','我穿过马路想躲开他,可他看见我,挥了挥手。装作没看见他也没用,于是我也挥手回应。我从来不喜欢碰见奈杰尔·戴克斯——他总是闲得没事干。不管你多忙,他总是坚持要跟着一起。我得想个办法,别让他跟着我逛一上午。“真巧在这儿碰到你!”他说,“你没忙什么吧?”“你介意我跟你一起去吗?”我还没说完他就问。我得赶紧想辙。“完全不介意,”我说,“不过我要去看牙医。”我以为这能让他打退堂鼓,可我错了。“那我也去,”他说,“候诊室里总有一堆东西可以读!”','{"q":"Listen and answer — Why did Elizabeth tell Nigel that she was going to the dentist?","options":["To stop Nigel from following her around all morning","Because she really had a toothache","Because Nigel worked at the dentist''s","Because she wanted him to come with her"],"answer_index":0}'::jsonb,'{"title":"动名词 -ing 作动词宾语","intro":"KS20+KS44 有些动词/结构后面只能接动名词(-ing),不接不定式:①动词 avoid/enjoy/deny/finish/mind/keep + doing;②结构 It''s no use doing(做…没用)、It''s not worth doing(不值得做)、be busy doing(忙于做)、prevent sb from doing(阻止某人做)。另:动名词可带逻辑主语(mind my coming);感官动词 see/hear/smell + 人/物 + doing;go/come + doing(go dancing)。","table":{"headers":["结构","例子"],"rows":[["动词 + doing","I avoid meeting him. / He enjoys playing football."],["It''s no use / not worth doing","It''s no use crying about it."],["prevent sb from doing","I prevented him from following me."],["mind + 逻辑主语 + doing","Would you mind my coming?"],["see/hear/smell + doing","I saw him coming. / go dancing"]]},"specialRules":[{"rule":"动名词可带逻辑主语,用物主代词:Would you mind opening…?(泛指)转成 Would you mind my opening…?(强调是“我”开);Fancy her writing a letter like that!","mark":"动名词逻辑主语"},{"rule":"反义疑问句前后相反:陈述肯定→疑问否定;陈述否定→疑问肯定。You''re not busy, are you?(前否后肯)/ He insists on coming, doesn''t he?(前肯后否)。","mark":"反义疑问句"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l68',1,NULL,'I crossed the street to avoid meeting him, but he saw me and waved. It was no use pretending I hadn''t seen him, so I waved back.','我穿过马路想躲开他,可他看见我,挥了挥手。装作没看见他也没用,于是我也挥手回应。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l68',2,NULL,'I never enjoy meeting Nigel Dykes — he never has anything to do. No matter how busy you are, he always insists on coming along.','我从来不喜欢碰见奈杰尔·戴克斯——他总是闲得没事干。不管你多忙,他总是坚持要跟着一起。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l68',3,NULL,'I had to think of a way of preventing him from following me around all morning. ''Fancy meeting you here!'' he said. ''You''re not busy doing anything, are you?''','我得想个办法,别让他跟着我逛一上午。“真巧在这儿碰到你!”他说,“你没忙什么吧?”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l68',4,NULL,'''Would you mind my coming with you?'' he asked before I could finish. I had to think fast. ''Not at all,'' I said, ''but I''m going to the dentist.''','“你介意我跟你一起去吗?”我还没说完他就问。我得赶紧想辙。“完全不介意,”我说,“不过我要去看牙医。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l68',5,NULL,'I thought that would stop him, but I was wrong. ''Then I''ll come too,'' he said. ''There''s always plenty to read in the waiting room!''','我以为这能让他打退堂鼓,可我错了。“那我也去,”他说,“候诊室里总有一堆东西可以读!”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l68','persistent','/pərˈsɪstənt/','adj','坚持不懈的;纠缠不休的','a persistent person you can''t get rid of') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l68','avoid','/əˈvɔɪd/','v','避免,躲开(+ doing)','I crossed the street to avoid meeting him.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l68','insist','/ɪnˈsɪst/','v','坚持(insist on doing)','he always insists on coming along') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l68','pretend','/prɪˈtend/','v','假装','It was no use pretending I hadn''t seen him.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
