INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l68','would you mind doing','',NULL,'/wʊd juː maɪnd ˈduːɪŋ/','Would you mind my coming with you?','你介意我跟你一起去吗?','Would you mind opening the window?','麻烦你把窗户打开好吗?') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l68','be busy doing','',NULL,'/biː ˈbɪzi ˈduːɪŋ/','Can''t you see I''m busy writing?','你没看见我忙着写东西吗?','She''s busy cooking dinner.','她正忙着做晚饭。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l68','Fancy meeting you here!','',NULL,'/ˈfænsi ˈmiːtɪŋ juː hɪr/','Fancy meeting you here!','真没想到在这儿见到你!','Fancy seeing you at the airport!','真巧在机场碰到你!') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',5,'am2_l68_gp1','choice','{"stem":"\"I crossed the street to avoid ___ him.\"(avoid 后接动名词)","options":["meeting","to meet","meet","met"],"answer_index":0,"stem_cn":"我穿过马路以躲开碰到他。","explanation_cn":"avoid 后面接动名词(-ing),不接不定式。✓ I crossed the street to avoid meeting him. ✗ to meet:avoid 不接不定式;✗ meet:缺 -ing;✗ met:过去式不作宾语。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',5,'am2_l68_gp1','choice','{"stem":"\"He enjoys ___ football.\"(enjoy 后接动名词)","options":["play","playing","to play","played"],"answer_index":1,"stem_cn":"他喜欢踢足球。","explanation_cn":"enjoy 后面接动名词。✓ He enjoys playing football. ✗ to play:enjoy 不接不定式;✗ play:缺 -ing;✗ played:过去式不合。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',5,'am2_l68_gp1','choice','{"stem":"\"He completely denies ___ it.\"(deny 后接动名词)","options":["taking","to take","take","took"],"answer_index":0,"stem_cn":"他完全否认拿了它。","explanation_cn":"deny 后面接动名词。✓ He completely denies taking it. ✗ to take:deny 不接不定式;✗ take:缺 -ing;✗ took:过去式不合。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',5,'am2_l68_gp1','choice','{"stem":"\"Have you finished ___ the letter?\"(finish 后接动名词)","options":["wrote","writing","write","to write"],"answer_index":1,"stem_cn":"你写完那封信了吗?","explanation_cn":"finish 后面接动名词。✓ Have you finished writing the letter? ✗ to write:finish 不接不定式;✗ write:缺 -ing;✗ wrote:过去式不合。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',5,'am2_l68_gp2','choice','{"stem":"\"It''s no use ___ about it.\"(It''s no use 后接动名词)","options":["to cry","cry","cried","crying"],"answer_index":3,"stem_cn":"为它哭是没用的。","explanation_cn":"It''s no use 后面接动名词。✓ It''s no use crying about it. ✗ to cry:此结构不接不定式;✗ cry:缺 -ing;✗ cried:过去式不合。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',5,'am2_l68_gp2','choice','{"stem":"\"It''s not worth ___ about.\"(be worth 后接动名词)","options":["worrying","worry","to worry","worried"],"answer_index":0,"stem_cn":"这不值得忧虑。","explanation_cn":"be (not) worth 后面接动名词。✓ It''s not worth worrying about. ✗ to worry:此结构不接不定式;✗ worry:缺 -ing;✗ worried:过去式不合。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',5,'am2_l68_gp2','choice','{"stem":"\"I had to think of a way of preventing him from ___ me around.\"(prevent sb from 后接动名词)","options":["followed","following","to follow","follow"],"answer_index":1,"stem_cn":"我得想办法别让他老跟着我。","explanation_cn":"prevent sb from 后面接动名词。✓ preventing him from following me around. ✗ to follow:from 后不接不定式;✗ follow:缺 -ing;✗ followed:过去式不合。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',5,'am2_l68_gp2','choice','{"stem":"\"Can''t you see I''m busy ___?\"(be busy 后接动名词)","options":["to write","wrote","write","writing"],"answer_index":3,"stem_cn":"你没看见我正忙着写东西吗?","explanation_cn":"be busy 后面接动名词。✓ I''m busy writing. ✗ to write:be busy 后不接不定式;✗ write:缺 -ing;✗ wrote:过去式不合。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',5,'am2_l68_gp3','choice','{"stem":"\"Would you mind ___ opening the window?\"(动名词的逻辑主语,''我''开窗你介意吗)","options":["for me","my","I","me to"],"answer_index":1,"stem_cn":"我开窗你介意吗?","explanation_cn":"动名词前可加物主代词作逻辑主语,表示是\"谁\"做的。✓ Would you mind my opening the window? ✗ I:主格不作动名词的逻辑主语;✗ me to:mind 后不接 to;✗ for me:此处习惯用物主代词 my。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',5,'am2_l68_gp3','choice','{"stem":"\"Fancy ___ writing a letter like that!\"(动名词的逻辑主语,''她''竟写了那样的信)","options":["her to","that she","she","her"],"answer_index":3,"stem_cn":"真想不到她写了那样一封信!","explanation_cn":"动名词前用物主代词作逻辑主语。✓ Fancy her writing a letter like that! ✗ she:主格不作逻辑主语;✗ her to:后面不接 to;✗ that she:此处用物主代词更简洁。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',5,'am2_l68_gp4','choice','{"stem":"\"I saw him ___ towards me.\"(感官动词 see + 人 + 动名词,表正在进行)","options":["come","to come","coming","came"],"answer_index":2,"stem_cn":"我看见他向我走来。","explanation_cn":"感官动词 see + 人 + 动名词,表示动作正在进行。✓ I saw him coming towards me. ✗ to come:see 后不接 to;✗ come:此处强调\"正在来\"用 -ing;✗ came:过去式不合。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',5,'am2_l68_gp4','choice','{"stem":"\"He heard me ___ the door.\"(感官动词 hear + 人 + 动名词)","options":["opening","open","to open","opened"],"answer_index":0,"stem_cn":"他听见我开门。","explanation_cn":"感官动词 hear + 人 + 动名词。✓ He heard me opening the door. ✗ to open:hear 后不接 to;✗ open:此处用 -ing;✗ opened:过去式不合。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',5,'am2_l68_gp4','choice','{"stem":"\"I can smell something ___.\"(感官动词 smell + 物 + 动名词)","options":["burn","burning","to burn","burnt"],"answer_index":1,"stem_cn":"我闻到什么东西烧焦了。","explanation_cn":"感官动词 smell + 物 + 动名词,表示正在进行。✓ I can smell something burning. ✗ to burn:smell 后不接 to;✗ burn:此处用 -ing;✗ burnt:过去分词不合此结构。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',5,'am2_l68_gp5','choice','{"stem":"\"Let''s go ___ tonight.\"(go + 动名词,表''去做某项活动'')","options":["danced","to dance","dance","dancing"],"answer_index":3,"stem_cn":"咱们今晚去跳舞吧。","explanation_cn":"go + 动名词,表示去做某项活动。✓ Let''s go dancing tonight. ✗ to dance:go 表活动时接 -ing;✗ dance:缺 -ing;✗ danced:过去式不合。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',5,'am2_l68_gp5','choice','{"stem":"\"I went ___ this morning.\"(go + 动名词:去买东西)","options":["to shop","shop","shopping","shopped"],"answer_index":2,"stem_cn":"今天上午我去买东西了。","explanation_cn":"go + 动名词,表示去做某项活动。✓ I went shopping this morning. ✗ to shop:go 表活动时接 -ing;✗ shop:缺 -ing;✗ shopped:过去式不合。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',5,'am2_l68_gp5','choice','{"stem":"\"Come ___ with me tomorrow.\"(come + 动名词:一起去游泳)","options":["swim","swimming","to swim","swam"],"answer_index":1,"stem_cn":"明天和我一起去游泳吧。","explanation_cn":"come + 动名词,表示一起去做某项活动。✓ Come swimming with me tomorrow. ✗ to swim:此结构接 -ing;✗ swim:缺 -ing;✗ swam:过去式不合。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',5,'am2_l68_gp6','choice','{"stem":"\"You''re not busy doing anything, ___?\"(反义疑问句:前面否定,后面就用肯定)","options":["are you","aren''t you","do you","don''t you"],"answer_index":0,"stem_cn":"你不忙,是吧?","explanation_cn":"陈述部分为否定(You''re not busy…),反义疑问部分用肯定 are you。✓ You''re not busy doing anything, are you? ✗ aren''t you:前否后不再否;✗ do you / don''t you:be 动词句子的反义疑问用 be。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',5,'am2_l68_gp6','choice','{"stem":"\"He always insists on coming with you, ___?\"(反义疑问句:前面肯定,后面就用否定)","options":["does he","don''t he","doesn''t he","isn''t he"],"answer_index":2,"stem_cn":"他总是坚持要跟你去,是不是?","explanation_cn":"陈述部分为肯定(He always insists…),反义疑问部分用否定 doesn''t he。✓ He always insists on coming with you, doesn''t he? ✗ does he:前肯后应否;✗ isn''t he:此句用实义动词,反义疑问用 does;✗ don''t he:第三人称单数用 doesn''t。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',6,NULL,'choice','{"stem":"美语里\"旅行(动名词)\"拼作:","options":["travelling","travling","traveuing","traveling"],"answer_index":3,"explanation_cn":"美语里 travel 加 -ing 只单写一个 l:traveling;英式双写 travelling。✓ I''m traveling next week. 我下周要出行。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',6,NULL,'choice','{"stem":"美语里\"取消(动名词)\"拼作:","options":["canceing","cancelling","canceling","cancling"],"answer_index":2,"explanation_cn":"美语里 cancel 加 -ing 只单写一个 l:canceling;英式双写 cancelling。✓ They are canceling the trip. 他们要取消这次旅行。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',6,NULL,'choice','{"stem":"persistent 的意思是:","options":["坚持的,纠缠不休的","慷慨的","害羞的","懒惰的"],"answer_index":0,"explanation_cn":"persistent = 坚持不懈的、纠缠不休的。✓ a persistent person you can''t get rid of 甩不掉的人。\n顺带记:懒惰的 = lazy;害羞的 = shy;慷慨的 = generous."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',6,NULL,'choice','{"stem":"avoid 的意思是:","options":["跟随","遇见","邀请","避开,回避"],"answer_index":3,"explanation_cn":"avoid = 避开、回避。✓ avoid meeting him 躲开碰到他。\n顺带记:遇见 = meet;邀请 = invite;跟随 = follow."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',6,NULL,'choice','{"stem":"insist 的意思是:","options":["拒绝","坚持,坚持要","忘记","怀疑"],"answer_index":1,"explanation_cn":"insist = 坚持、坚持要(insist on doing)。✓ he insists on coming 他坚持要来。\n顺带记:拒绝 = refuse;忘记 = forget;怀疑 = doubt."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',6,NULL,'choice','{"stem":"pretend 的意思是:","options":["假装","承认","后悔","证明"],"answer_index":0,"explanation_cn":"pretend = 假装。✓ It''s no use pretending 装作…也没用。\n顺带记:承认 = admit;证明 = prove;后悔 = regret."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',7,NULL,'cloze','{"stem":"第 1 空","context":"I crossed the street to avoid ___1___ him, but he saw me. It was no use ___2___ that I hadn''t seen him. He always insists on ___3___ with you. I had to think of a way of preventing him from ___4___ me around.","blank_no":1,"options":["meeting","to meet","meet","met"],"answer_index":0,"explanation_cn":"avoid 后接动名词。✓ to avoid meeting him.\n✗ to meet:不接不定式;✗ meet:缺 -ing;✗ met:过去式不合。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',7,NULL,'cloze','{"stem":"第 2 空","context":"I crossed the street to avoid ___1___ him, but he saw me. It was no use ___2___ that I hadn''t seen him. He always insists on ___3___ with you. I had to think of a way of preventing him from ___4___ me around.","blank_no":2,"options":["pretending","to pretend","pretend","pretended"],"answer_index":0,"explanation_cn":"It''s no use 后接动名词。✓ It was no use pretending that I hadn''t seen him.\n✗ to pretend:此结构不接不定式;✗ pretend:缺 -ing;✗ pretended:过去式不合。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',7,NULL,'cloze','{"stem":"第 3 空","context":"I crossed the street to avoid ___1___ him, but he saw me. It was no use ___2___ that I hadn''t seen him. He always insists on ___3___ with you. I had to think of a way of preventing him from ___4___ me around.","blank_no":3,"options":["coming","to come","come","came"],"answer_index":0,"explanation_cn":"insist on 后接动名词。✓ He always insists on coming with you.\n✗ to come:on 后不接不定式;✗ come:缺 -ing;✗ came:过去式不合。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',7,NULL,'cloze','{"stem":"第 4 空","context":"I crossed the street to avoid ___1___ him, but he saw me. It was no use ___2___ that I hadn''t seen him. He always insists on ___3___ with you. I had to think of a way of preventing him from ___4___ me around.","blank_no":4,"options":["following","to follow","follow","followed"],"answer_index":0,"explanation_cn":"prevent sb from 后接动名词。✓ preventing him from following me around.\n✗ to follow:from 后不接不定式;✗ follow:缺 -ing;✗ followed:过去式不合。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',8,NULL,'choice','{"stem":"Why did Elizabeth cross the street?","options":["To catch a bus","To meet the dentist","To avoid meeting Nigel Dykes","To buy something"],"answer_index":2,"explanation_cn":"课文说 I crossed the street to avoid meeting him(Nigel Dykes)。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',8,NULL,'choice','{"stem":"What does Nigel Dykes always insist on doing?","options":["Coming with you, no matter how busy you are","Telling long stories","Leaving early","Paying for everything"],"answer_index":0,"explanation_cn":"课文说 No matter how busy you are, he always insists on coming along。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',8,NULL,'choice','{"stem":"Why did Elizabeth say she was going to the dentist?","options":["Because she had a bad toothache","Because she liked her dentist","Because Nigel asked her to","To stop Nigel from following her around all morning"],"answer_index":3,"explanation_cn":"课文说她谎称去看牙医,是想 preventing him from following me around all morning。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',9,NULL,'choice','{"stem":"你想说\"我过马路以躲开碰到他\"(avoid 后接动名词):","options":["I crossed the street to avoid meet him.","I crossed the street to avoid meeting him.","I crossed the street for avoid meeting him.","I crossed the street to avoid to meet him."],"answer_index":1,"explanation_cn":"avoid 后接动名词。✓ I crossed the street to avoid meeting him. 场合:说自己特意躲开某人。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',9,NULL,'choice','{"stem":"你想客气地问\"我跟你一起去你介意吗?\"(mind + 逻辑主语 + 动名词):","options":["Would you mind come with you?","Would you mind I come with you?","Would you mind my coming with you?","Would you mind me to come with you?"],"answer_index":2,"explanation_cn":"客气请求用 Would you mind + my + 动名词(my 表示是\"我\"要做)。✓ Would you mind my coming with you? 场合:委婉地问对方是否介意自己一起去。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',9,NULL,'choice','{"stem":"你想说\"咱们去跳舞吧\"(go + 动名词):","options":["Let''s go dancing.","Let''s go dance.","Let''s go to dance.","Let''s going dancing."],"answer_index":0,"explanation_cn":"go + 动名词表示\"去做某项活动\"。✓ Let''s go dancing. 场合:提议一起去做某活动。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',10,NULL,'choice','{"stem":"persistent 的意思是:","options":["害羞的","懒惰的","坚持的,纠缠不休的","慷慨的"],"answer_index":2,"explanation_cn":"persistent = 坚持不懈的、纠缠不休的。✓ a persistent person 甩不掉的人。\n顺带记:懒惰的 = lazy;害羞的 = shy;慷慨的 = generous."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',10,NULL,'choice','{"stem":"avoid 的意思是:","options":["邀请","遇见","跟随","避开,回避"],"answer_index":3,"explanation_cn":"avoid = 避开、回避。✓ avoid meeting him 躲开碰到他。\n顺带记:遇见 = meet;邀请 = invite;跟随 = follow."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',10,NULL,'choice','{"stem":"\"He enjoys ___ football.\"(enjoy 后接动名词)","options":["playing","played","play","to play"],"answer_index":0,"stem_cn":"他喜欢踢足球。","explanation_cn":"enjoy 后接动名词。✓ He enjoys playing football.\n✗ to play:enjoy 不接不定式;✗ play:缺 -ing;✗ played:过去式不合。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',10,NULL,'choice','{"stem":"\"I saw him ___ towards me.\"(感官动词 see + 人 + 动名词)","options":["came","come","to come","coming"],"answer_index":3,"stem_cn":"我看见他向我走来。","explanation_cn":"感官动词 see + 人 + 动名词。✓ I saw him coming towards me.\n✗ to come:see 后不接 to;✗ come:此处用 -ing;✗ came:过去式不合。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',10,NULL,'choice','{"stem":"像 avoid/enjoy/mind/finish 这样的动词后面接:","options":["to + 动词原形","动词原形","动词的 -ing 形式","动词过去式"],"answer_index":2,"explanation_cn":"avoid/enjoy/mind/finish 等动词后面只能接动名词(动词的 -ing 形式),不接不定式。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',10,NULL,'choice','{"stem":"\"Fancy meeting you here!\" 表达的意思是:","options":["很高兴见到你","真没想到在这儿见到你(表惊讶)","我不想见你","我们约好在这儿见"],"answer_index":1,"explanation_cn":"Fancy meeting you here! 是地道口语,表示\"真巧、真没想到在这儿碰见你\",带惊讶语气。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',10,NULL,'choice','{"stem":"How did Nigel end up going with Elizabeth even though she tried to avoid him?","options":["He followed her secretly","She invited him along","He was already going to the dentist","He offered to come with her before she finished speaking, and said he''d wait at the dentist too"],"answer_index":3,"passage":"I crossed the street to avoid meeting him, but he saw me and waved. It was no use pretending I hadn''t seen him, so I waved back. I never enjoy meeting Nigel Dykes — he never has anything to do. No matter how busy you are, he always insists on coming along. I had to think of a way of preventing him from following me around all morning. ''Fancy meeting you here!'' he said. ''You''re not busy doing anything, are you?'' ''Would you mind my coming with you?'' he asked before I could finish. I had to think fast. ''Not at all,'' I said, ''but I''m going to the dentist.'' I thought that would stop him, but I was wrong. ''Then I''ll come too,'' he said. ''There''s always plenty to read in the waiting room!''","explanation_cn":"课文说 he asked \"Would you mind my coming with you?\" before she finished, and even said he''d come to the dentist because there''s plenty to read。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',10,NULL,'choice','{"stem":"Why was going to the dentist not enough to get rid of Nigel?","options":["He was afraid of dentists","He went home instead","He said there''s always plenty to read in the waiting room, so he''d come anyway","He had his own appointment"],"answer_index":2,"passage":"I crossed the street to avoid meeting him, but he saw me and waved. It was no use pretending I hadn''t seen him, so I waved back. I never enjoy meeting Nigel Dykes — he never has anything to do. No matter how busy you are, he always insists on coming along. I had to think of a way of preventing him from following me around all morning. ''Fancy meeting you here!'' he said. ''You''re not busy doing anything, are you?'' ''Would you mind my coming with you?'' he asked before I could finish. I had to think fast. ''Not at all,'' I said, ''but I''m going to the dentist.'' I thought that would stop him, but I was wrong. ''Then I''ll come too,'' he said. ''There''s always plenty to read in the waiting room!''","explanation_cn":"课文说 ''Then I''ll come too… There''s always plenty to read in the waiting room!''"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',10,NULL,'choice','{"stem":"What is Nigel Dykes like?","options":["He never has anything to do and always insists on coming with you","He is always very busy","He hates company","He is a dentist"],"answer_index":0,"audio":"I crossed the street to avoid meeting him, but he saw me and waved. It was no use pretending I hadn''t seen him, so I waved back. I never enjoy meeting Nigel Dykes — he never has anything to do. No matter how busy you are, he always insists on coming along. I had to think of a way of preventing him from following me around all morning. ''Fancy meeting you here!'' he said. ''You''re not busy doing anything, are you?'' ''Would you mind my coming with you?'' he asked before I could finish. I had to think fast. ''Not at all,'' I said, ''but I''m going to the dentist.'' I thought that would stop him, but I was wrong. ''Then I''ll come too,'' he said. ''There''s always plenty to read in the waiting room!''","explanation_cn":"课文说 He never has anything to do… he always insists on coming with you。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l68',10,NULL,'choice','{"stem":"What did Elizabeth do when she first saw Nigel?","options":["She pretended to be someone else","She invited him for coffee","She crossed the street to avoid him, but he saw her, so she waved","She ran away"],"answer_index":2,"audio":"I crossed the street to avoid meeting him, but he saw me and waved. It was no use pretending I hadn''t seen him, so I waved back. I never enjoy meeting Nigel Dykes — he never has anything to do. No matter how busy you are, he always insists on coming along. I had to think of a way of preventing him from following me around all morning. ''Fancy meeting you here!'' he said. ''You''re not busy doing anything, are you?'' ''Would you mind my coming with you?'' he asked before I could finish. I had to think fast. ''Not at all,'' I said, ''but I''m going to the dentist.'' I thought that would stop him, but I was wrong. ''Then I''ll come too,'' he said. ''There''s always plenty to read in the waiting room!''","explanation_cn":"课文说 I crossed the street to avoid meeting him, but he saw me and waved… so I waved back。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l69',2,9,69,'The old car comes back to life','老爷车重获新生','被动语态综合复习(方案B换情节·原 L69 KS10/21/34/45 考点原样承载):一般过去被动 was/were made、情态被动 can/could/must be done、现在完成被动 has been done、过去完成被动 had been kept、过去进行被动 was being cleaned、完成式非谓语被动 having been stored','上个月,一辆稀有的老爷车被送到了我们博物馆——博物馆最近才收购了它。它1925年在德国制造,一共只造过十辆。多年来它一直被存放在一个旧车库里,几乎被人遗忘。送来时,引擎几乎发动不了。“它能修好,”我们的首席技师说,并指示他的团队检查每一个零件。在清理这辆车时,座位下面发现了制造商的名字。由于被存放了这么久,这辆车需要大量的修理。每个零件都被仔细检查,坏的都被更换。随着信心不断增强,团队一直干下去,几个月后这辆车已被完全修复到它最初的状态。如今它受到每一位参观博物馆的人的赞赏。','{"q":"Listen and answer — What happened to the old car at the museum?","options":["It was fully restored to its original condition after months of work","It was sold to a private collector","It was scrapped for parts","It was left in the garage"],"answer_index":0}'::jsonb,'{"title":"被动语态综合复习","intro":"各种时态的被动都是 be + 过去分词,时态变在 be 上:一般过去 was made、情态 can/could/must be done、过去进行 was being cleaned、过去完成 had been kept、现在完成 has been restored。介词或连词后用动名词被动,完成式为 having been done(Having been stored for years…)。对过去的推测(被动)用 must have been + 过去分词。","table":{"headers":["时态/形式","被动"],"rows":[["一般过去","was made / were built"],["情态/推测","can be repaired / must have been kept"],["过去进行","was being cleaned"],["过去完成","had been kept / had been stored"],["现在完成","has been restored"],["完成式非谓语","having been stored"]]},"specialRules":[{"rule":"完成式的非谓语被动用 having been + 过去分词,作状语说明原因或先发生:Having been stored for so long, the car needed a lot of work。","mark":"having been done"},{"rule":"对过去情况的推测(被动)用 must have been + 过去分词:It must have been kept in a dry garage(它一定是被放在干燥的车库里)。","mark":"must have been done"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l69',1,NULL,'Last month, a rare old car was brought to our museum, which had recently acquired it. It was made in Germany in 1925, and only ten of them were ever built.','上个月,一辆稀有的老爷车被送到了我们博物馆——博物馆最近才收购了它。它1925年在德国制造,一共只造过十辆。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l69',2,NULL,'For years it had been kept in an old garage and almost forgotten. When it arrived, the engine could hardly be started.','多年来它一直被存放在一个旧车库里,几乎被人遗忘。送来时,引擎几乎发动不了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l69',3,NULL,'''It can be repaired,'' our chief mechanic said, and he instructed his team to check every part. While the car was being cleaned, the maker''s name was found under the seat.','“它能修好,”我们的首席技师说,并指示他的团队检查每一个零件。在清理这辆车时,座位下面发现了制造商的名字。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l69',4,NULL,'Having been stored for so long, the car needed a great deal of work. Every part was carefully checked, and the broken ones were replaced.','由于被存放了这么久,这辆车需要大量的修理。每个零件都被仔细检查,坏的都被更换。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l69',5,NULL,'With growing confidence, the team worked on, and after months the car has been fully restored to its original condition. Now it is admired by everyone who visits the museum.','随着信心不断增强,团队一直干下去,几个月后这辆车已被完全修复到它最初的状态。如今它受到每一位参观博物馆的人的赞赏。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l69','instruct','/ɪnˈstrʌkt/','v','指示,命令','he instructed his team to check every part') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l69','acquire','/əˈkwaɪr/','v','取得,获得','the museum had recently acquired it') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l69','confidence','/ˈkɑːnfɪdəns/','n','信心','With growing confidence, the team worked on.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
